// Pick the source document from the item's attachments.
// Output files written back by an earlier run are ignored, so a re-run
// of a partially processed item cannot feed its own output back in.

const OUTPUT_MARKERS = [
  '_Translated by AI',
  '_AI Translation Quality Report',
  '_AI Translation Used Terminology',
  '_AI Translation State',
];

const attachments = $input.first().json.value || [];

const candidates = attachments.filter((a) => {
  const name = a.name || '';
  return !OUTPUT_MARKERS.some((m) => name.includes(m));
});

if (candidates.length === 0) {
  throw new Error('No source attachment found on the list item (only generated output files present).');
}

if (candidates.length > 1) {
  const names = candidates.map((c) => c.name).join(', ');
  throw new Error(`Expected exactly one source attachment, found ${candidates.length}: ${names}`);
}

const source = candidates[0];
const dotIndex = source.name.lastIndexOf('.');
const baseName = dotIndex > 0 ? source.name.slice(0, dotIndex) : source.name;

return [{
  json: {
    sourceName: source.name,
    sourceUrl: source['@microsoft.graph.downloadUrl'] || source.contentUrl,
    baseName,
  },
}];

// Initialise the per-document loop state.
// callCount, stagesCompleted and the budget baseline live here and are
// carried through every iteration by the 'Merge loop state' node.

const picked = $('Pick source attachment').first().json;
const itemId = $('One document at a time').first().json.id;

return [{
  json: {
    itemId,
    sourceName: picked.sourceName,
    baseName: picked.baseName,
    callCount: 0,
    stateBlock: null,
    statusBlock: null,
    runState: 'INCOMPLETE',
    nextStage: 'E1',
    stagesCompleted: '',
    previousStagesCompleted: '',
    noProgressStrikes: 0,
    budgetBaseline: null,
    budgetConsumed: null,
    collectedFiles: [],
    abortReason: null,
  },
  binary: {
    source: $('Download source file').first().binary.source,
    prompt: $('Read prompt file').first().binary.data,
  },
}];

// Turn the balance reading into the three lines the prompt expects.
//
// BUDGET_MODE decides the direction of the subtraction:
//   remaining  -> endpoint reports credit left   -> consumed = baseline - current
//   cumulative -> endpoint reports spend to date -> consumed = current - baseline
// Getting this backwards puts a negative number in the quality report, which
// is why it is an explicit setting and not inferred.

const cfg = $('Config').first().json;

// 'Budget enabled?' passes its input through unchanged, so it still holds this
// iteration's loop state. The HTTP node before us replaced the item with the
// API response.
const gate = $('Budget enabled?').first();
const state = gate.json;

// TODO: adjust to the real response shape of the budget endpoint.
const raw = $input.first().json;
const current = Number(raw?.balance ?? raw?.value ?? raw?.amount);

let baseline = state.budgetBaseline;
let consumed = null;

if (Number.isFinite(current)) {
  if (baseline === null || baseline === undefined) {
    baseline = current;
    consumed = 0;
  } else {
    consumed = cfg.budgetMode === 'cumulative'
      ? current - baseline
      : baseline - current;
    consumed = Math.round(consumed * 10000) / 10000;
  }
}

// No usable reading: no lines at all. The prompt then reports 'not available'
// rather than an invented figure.
const lines = consumed === null
  ? ''
  : `budget_consumed: ${consumed}\nbudget_unit: ${cfg.budgetUnit}\nbudget_calls: ${state.callCount + 1}\n\n`;

return [{
  json: { ...state, budgetBaseline: baseline, budgetConsumed: consumed, budgetLines: lines },
  binary: gate.binary,
}];

// Budget disabled: no lines, no baseline. The prompt reports 'not available',
// which is its normal, documented case.
const item = $input.first();
return [{ json: { ...item.json, budgetLines: '' }, binary: item.binary }];

// Build the message body for this call.
//
// First call  -> process the attached file.
// Follow-up   -> hand back the last complete state block verbatim.
//
// The prompt and the source file are attached on EVERY call: a follow-up
// may land in a fresh session where neither is present.

const state = $input.first().json;
const isFirst = state.callCount === 0 || !state.stateBlock;

const body = isFirst
  ? `${state.budgetLines}Process the attached file according to the attached prompt file.`
  : `${state.budgetLines}Continue the processing run described by the processing state below.\n` +
    `Resume at the stage given in next_stage. Do not repeat completed stages.\n\n` +
    state.stateBlock;

return [{
  json: { ...state, messageBody: body, callCount: state.callCount + 1 },
  binary: $('Init loop state').first().binary,
}];

// Parse the response and decide whether to loop again.
//
// Two rules carry the whole mechanism:
//  1. Take the LAST COMPLETE status/state block pair. The turn can be cut
//     off mid-output, so a block near the end may be truncated.
//  2. A truncated block is discarded; the preceding complete one wins.
//
// The state block carries the full translated text and is the single most
// likely thing to be cut off at the step limit. If no complete pair exists
// at all, we cannot resume and must treat the next call as a first call.

const cfg = $('Config').first().json;
const prev = $('Build call body').first().json;
const res = $input.first().json;

const text = typeof res.body === 'string'
  ? res.body
  : (res.body?.content ?? res.body?.message ?? res.body?.choices?.[0]?.message?.content ?? JSON.stringify(res.body ?? ''));

const httpOk = !res.statusCode || (res.statusCode >= 200 && res.statusCode < 300);

function lastComplete(open, close) {
  const re = new RegExp(`${open}[\\s\\S]*?${close}`, 'g');
  const found = text.match(re);
  return found && found.length ? found[found.length - 1] : null;
}

const statusBlock = lastComplete('===AI-TRANSLATION-STATUS===', '===END-STATUS===');
const stateBlock = lastComplete('===AI-TRANSLATION-STATE===', '===END-STATE===');

// A state block whose JSON does not parse is unusable even if both
// delimiters are present — the model may have emitted the closing line
// after a truncated body.
let stateUsable = null;
if (stateBlock) {
  const inner = stateBlock
    .replace('===AI-TRANSLATION-STATE===', '')
    .replace('===END-STATE===', '')
    .trim();
  try {
    JSON.parse(inner);
    stateUsable = stateBlock;
  } catch (e) {
    stateUsable = null;
  }
}

function statusField(name) {
  if (!statusBlock) return null;
  const m = statusBlock.match(new RegExp(`^${name}:\\s*(.*)$`, 'm'));
  return m ? m[1].trim() : null;
}

const runState = statusField('run_state') || 'INCOMPLETE';
const nextStage = statusField('next_stage') || prev.nextStage;
const stagesCompleted = statusField('stages_completed') || '';
const blockedStep = statusField('blocked_step');

// Exit condition: no forward progress across two consecutive calls.
const madeProgress = stagesCompleted !== prev.previousStagesCompleted;
const strikes = madeProgress ? 0 : prev.noProgressStrikes + 1;

let abortReason = null;
if (!httpOk) {
  abortReason = `myGenAssist returned HTTP ${res.statusCode}`;
} else if (!statusBlock) {
  abortReason = prev.callCount > 1
    ? 'No parsable status block in two consecutive responses'
    : null; // first call without a block: retried once as a fresh call
} else if (strikes >= 2) {
  abortReason = `No progress across two consecutive calls (stages_completed stuck at "${stagesCompleted}")`;
} else if (prev.callCount >= cfg.maxCalls) {
  abortReason = `Call limit of ${cfg.maxCalls} reached without COMPLETE`;
} else if (blockedStep) {
  abortReason = `Prompt reported blocked_step: ${blockedStep}`;
}

const isComplete = runState === 'COMPLETE';

return [{
  json: {
    ...prev,
    statusBlock,
    stateBlock: stateUsable || prev.stateBlock,
    stateBlockTruncated: Boolean(stateBlock) && !stateUsable,
    runState,
    nextStage,
    stagesCompleted,
    previousStagesCompleted: stagesCompleted,
    noProgressStrikes: strikes,
    blockedStep,
    abortReason,
    isComplete,
    responseText: text,
    keepLooping: !isComplete && !abortReason,
  },
  binary: $('Build call body').first().binary,
}];

// Collect the output files.
//
// Two paths, because it is not yet settled whether myGenAssist returns
// files through the API at all (open question in resume-loop.md):
//
//   A) attachments present -> pass them through unchanged
//   B) text only           -> rebuild what we can from the response
//
// Path B cannot produce a faithful DOCX. It writes the Markdown version
// (which the prompt emits as plain text) and records in NotesForReviewer
// that DOCX and CSV are missing, rather than silently delivering less.

const state = $input.first().json;
const res = $('myGenAssist call').first();
const text = state.responseText || '';
const base = state.baseName;

const incoming = res.binary || {};
const attachmentKeys = Object.keys(incoming).filter((k) => k !== 'prompt' && k !== 'source');

if (attachmentKeys.length > 0) {
  const binary = {};
  const names = [];
  attachmentKeys.forEach((k, i) => {
    binary[`file_${i}`] = incoming[k];
    names.push(incoming[k].fileName || k);
  });
  return [{
    json: { ...state, deliveryPath: 'attachments', collectedFiles: names, missingFiles: [] },
    binary,
  }];
}

// Path B — reconstruct from text.
const binary = {};
const collected = [];
const missing = [];

// The Markdown version starts at its YAML frontmatter and runs to the end
// of that fenced section. Everything the prompt prints around it (status
// and state blocks) is stripped.
const mdMatch = text.match(/^---\n[\s\S]*?\n---\n[\s\S]*?(?=\n===AI-TRANSLATION-|$)/m);
if (mdMatch) {
  binary.markdown = {
    data: Buffer.from(mdMatch[0], 'utf8').toString('base64'),
    mimeType: 'text/markdown',
    fileName: `${base}_Translated by AI.md`,
  };
  collected.push(`${base}_Translated by AI.md`);
} else {
  missing.push(`${base}_Translated by AI.md`);
}

missing.push(`${base}_Translated by AI.docx`);
missing.push(`${base}_AI Translation Quality Report.docx`);
missing.push(`${base}_AI Translation Used Terminology.csv`);

return [{
  json: { ...state, deliveryPath: 'text-only', collectedFiles: collected, missingFiles: missing },
  binary,
}];

parameters.jsonBody:
={{ JSON.stringify({
  Status: $('Collect output files').first().json.deliveryPath === 'attachments' ? 'Done' : 'Done (partial)',
  CallCount: $('Collect output files').first().json.callCount,
  BudgetConsumed: $('Collect output files').first().json.budgetConsumed,
  BudgetUnit: $('Config').first().json.budgetUnit,
  ProcessingFinishedAt: new Date().toISOString(),
  NotesForReviewer: ($('Collect output files').first().json.missingFiles || []).length
    ? 'myGenAssist returned text only. Missing: ' + $('Collect output files').first().json.missingFiles.join(', ')
    : ''
}) }}

