// Drop the translated text from memory.
//
// The state block carries the full document content. Per the retention
// rule it is kept only for the duration of the loop and must not be
// persisted or passed on once the run ends.

const s = $input.first().json;

return [{
  json: {
    itemId: s.itemId,
    sourceName: s.sourceName,
    outcome: 'done',
    deliveryPath: s.deliveryPath,
    callCount: s.callCount,
    budgetConsumed: s.budgetConsumed,
  },
}];

// Route the document to manual review.
//
// Never discard silently: the source stays on the list item, the reason
// and the reached stage are written back so the case can be followed up.

const s = $input.first().json;

let reason = s.abortReason || 'Unknown abort';
if (s.stateBlockTruncated) {
  reason += ' | last state block was truncated (likely cut off at the step limit) — the full translated text did not fit in the response';
}

return [{
  json: {
    itemId: s.itemId,
    reason,
    stagesCompleted: s.stagesCompleted || '(none)',
    nextStage: s.nextStage,
    callCount: s.callCount,
  },
}];

parameters.jsonBody:
={{ JSON.stringify({
  Status: 'Manual review',
  CallCount: $json.callCount,
  ProcessingFinishedAt: new Date().toISOString(),
  NotesForReviewer: $json.reason + ' | stages completed: ' + $json.stagesCompleted
}) }}
